    ("header", "std_msgs/msg/Header", False, None, False, None, None),
    ("results", "vision_msgs/msg/ObjectHypothesisWithPose", True, None, False, None, None),
    ("bbox", "vision_msgs/msg/BoundingBox2D", False, None, False, None, None),
    ("id", "string", False, None, False, None, None),
